using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering.Universal;

/// <summary>
/// Projects Perseverance wheel tracks onto the terrain with URP decals, from rover_tracks.json
/// (generated by Tools/RoverTracks/make_rover_tracks.py from the mission drive path).
/// Two ruts follow the drive path; at turn-in-place points each of the six wheels leaves a rolling arc.
///
/// The full traverse is ~46 km (~100,000 decals), far too many to keep alive, so tracks are STREAMED: the data is
/// split into square cells and only cells within <see cref="streamRadius"/> of the player (Play mode) or the Scene
/// view camera (Edit mode) get decal objects. Cells are created/removed as you move. Nothing is saved in the scene.
/// Requires the Decal renderer feature on the active URP renderer.
/// </summary>
[ExecuteAlways]
[DisallowMultipleComponent]
public class MarsRoverTracks : MonoBehaviour
{
    [Serializable] class Group { public int sol; public string side; public float[] segments; }
    [Serializable] class Turn { public int sol; public float x; public float y; public float heading; public float turn_deg; public int tile; }
    [Serializable] class TrackData
    {
        public float tile_length_m; public int segment_stride; public Group[] ruts;
        public float turn_tile_size_m; public int turn_atlas_cols; public int turn_atlas_rows; public Turn[] turns;
    }

    struct Item { public bool turn; public Vector2 xz; public float heading, length, width, uvBias, fade; public int tile; }

    const string LogPrefix = "[MarsRoverTracks] ";
    const string RootName = "Rover Tracks (generated)";

    [SerializeField] TextAsset trackData;
    [Tooltip("Terrain to project onto. If empty, the first Terrain in the scene is used.")]
    [SerializeField] Terrain terrain;
    [SerializeField] Material rutMaterial;
    [Tooltip("Decal material using the turn-in-place atlas.")]
    [SerializeField] Material turnMaterial;

    [Header("Display")]
    [SerializeField] bool showDriveRuts = true;
    [SerializeField] bool showTurnInPlaceArcs = true;
    [Tooltip("Decals further than this from the camera are not drawn.")]
    [SerializeField, Min(5f)] float drawDistance = 80f;
    [Tooltip("Overall strength of the tracks (decal opacity multiplier).")]
    [SerializeField, Range(0f, 1f)] float strength = 1f;
    [Tooltip("Vertical size of each projection box in metres; must cover the terrain's slope within one segment.")]
    [SerializeField, Min(0.1f)] float projectionDepth = 3f;

    [Header("Streaming")]
    [Tooltip("Decal objects exist only within this distance of the player / Scene view camera (m). Keep above Draw Distance.")]
    [SerializeField, Min(20f)] float streamRadius = 150f;
    [Tooltip("Size of one streaming cell (m).")]
    [SerializeField, Min(16f)] float cellSize = 64f;
    [Tooltip("Who the tracks stream around in Play mode. If empty, the MarsPlayerController (or main camera) is used.")]
    [SerializeField] Transform focus;

    Transform root;
    TrackData data;
    readonly Dictionary<Vector2Int, List<Item>> cells = new Dictionary<Vector2Int, List<Item>>();
    readonly Dictionary<Vector2Int, Transform> live = new Dictionary<Vector2Int, Transform>();
    Vector3 lastFocus = new Vector3(float.MaxValue, 0f, 0f);
    int totalItems;

    public int TotalDecals => totalItems;
    public int LiveDecals { get { int n = 0; foreach (var c in live) n += c.Value.childCount; return n; } }

    void OnEnable()
    {
        Load();
#if UNITY_EDITOR
        UnityEditor.EditorApplication.update += EditorTick;
#endif
    }

    void OnDisable()
    {
#if UNITY_EDITOR
        UnityEditor.EditorApplication.update -= EditorTick;
#endif
        ClearLive();
    }

    void OnValidate()
    {
#if UNITY_EDITOR
        UnityEditor.EditorApplication.delayCall += () => { if (this != null && isActiveAndEnabled) Build(); };
#endif
    }

    /// <summary>Re-read the data and rebuild the tracks around the current focus.</summary>
    [ContextMenu("Rebuild Tracks")]
    public void Build()
    {
        Load();
        lastFocus = new Vector3(float.MaxValue, 0f, 0f);
        Stream(force: true);
    }

    void Update()
    {
        if (Application.isPlaying) Stream(force: false);
    }

#if UNITY_EDITOR
    double nextEditorTick;
    void EditorTick()
    {
        if (Application.isPlaying || this == null || !isActiveAndEnabled) return;
        if (UnityEditor.EditorApplication.timeSinceStartup < nextEditorTick) return;
        nextEditorTick = UnityEditor.EditorApplication.timeSinceStartup + 0.25;
        Stream(force: false);
    }
#endif

    // ------------------------------------------------------------------ data
    void Load()
    {
        ClearLive();
        cells.Clear(); totalItems = 0; data = null;
        if (trackData == null || rutMaterial == null) return;
        if (terrain == null) terrain = FindAnyObjectByType<Terrain>();
        if (terrain == null) { Debug.LogWarning(LogPrefix + "No Terrain found.", this); return; }
        try { data = JsonUtility.FromJson<TrackData>(trackData.text); }
        catch (Exception e) { Debug.LogError(LogPrefix + "Could not read track data: " + e.Message, this); return; }

        Vector3 size = terrain.terrainData.size, origin = terrain.transform.position;
        Vector2 ToXZ(float fx, float fy) => new Vector2(origin.x + fx * size.x, origin.z + fy * size.z);

        if (showDriveRuts && data.ruts != null)
        {
            int stride = data.segment_stride >= 7 ? data.segment_stride : 6;
            foreach (Group g in data.ruts)
            {
                float[] s = g.segments;
                if (s == null) continue;
                for (int i = 0; i + stride - 1 < s.Length; i += stride)
                    Add(new Item
                    {
                        xz = ToXZ(s[i], s[i + 1]), heading = s[i + 2], length = s[i + 3], width = s[i + 4], uvBias = s[i + 5],
                        fade = stride >= 7 ? s[i + 6] : 1f,
                    });
            }
        }
        if (showTurnInPlaceArcs && turnMaterial != null && data.turns != null && data.turn_atlas_cols > 0)
            foreach (Turn t in data.turns)
                Add(new Item { turn = true, xz = ToXZ(t.x, t.y), heading = t.heading, tile = t.tile, fade = 1f });
    }

    void Add(Item it)
    {
        var key = new Vector2Int(Mathf.FloorToInt(it.xz.x / cellSize), Mathf.FloorToInt(it.xz.y / cellSize));
        if (!cells.TryGetValue(key, out List<Item> list)) cells[key] = list = new List<Item>();
        list.Add(it);
        totalItems++;
    }

    // ------------------------------------------------------------------ streaming
    Vector3? FocusPosition()
    {
        if (Application.isPlaying)
        {
            if (focus == null)
            {
                var pc = FindAnyObjectByType<MarsPlayerController>();
                if (pc != null) focus = pc.transform;
                else if (Camera.main != null) focus = Camera.main.transform;
            }
            return focus != null ? focus.position : (Vector3?)null;
        }
#if UNITY_EDITOR
        var sv = UnityEditor.SceneView.lastActiveSceneView;
        if (sv != null && sv.camera != null) return sv.camera.transform.position;
#endif
        return focus != null ? focus.position : (Vector3?)null;
    }

    void Stream(bool force)
    {
        if (data == null || terrain == null) return;
        Vector3? f = FocusPosition();
        if (f == null) return;
        Vector3 p = f.Value;
        if (!force && (new Vector2(p.x - lastFocus.x, p.z - lastFocus.z)).sqrMagnitude < (cellSize * 0.25f) * (cellSize * 0.25f)) return;
        lastFocus = p;

        // Height above the ground matters too: from high up (e.g. the Scene view over the map) tracks are invisible.
        float above = p.y - (terrain.transform.position.y + terrain.SampleHeight(p));
        float radius = above > streamRadius ? 0f : streamRadius;

        int r = Mathf.CeilToInt(radius / cellSize);
        var centre = new Vector2Int(Mathf.FloorToInt(p.x / cellSize), Mathf.FloorToInt(p.z / cellSize));
        var wanted = new HashSet<Vector2Int>();
        if (radius > 0f)
            for (int dx = -r; dx <= r; dx++)
                for (int dz = -r; dz <= r; dz++)
                {
                    var k = new Vector2Int(centre.x + dx, centre.y + dz);
                    if (!cells.ContainsKey(k)) continue;
                    Vector2 cmin = new Vector2(k.x * cellSize, k.y * cellSize);
                    float nx = Mathf.Clamp(p.x, cmin.x, cmin.x + cellSize) - p.x, nz = Mathf.Clamp(p.z, cmin.y, cmin.y + cellSize) - p.z;
                    if (nx * nx + nz * nz <= radius * radius) wanted.Add(k);
                }

        var drop = new List<Vector2Int>();
        foreach (var kv in live) if (!wanted.Contains(kv.Key)) drop.Add(kv.Key);
        foreach (var k in drop) { if (live[k] != null) DestroyObj(live[k].gameObject); live.Remove(k); }
        foreach (var k in wanted) if (!live.ContainsKey(k)) live[k] = BuildCell(k, cells[k]);
    }

    Transform BuildCell(Vector2Int key, List<Item> items)
    {
        if (root == null) root = transform.Find(RootName);
        if (root == null)
        {
            root = new GameObject(RootName).transform;
            root.gameObject.hideFlags = HideFlags.DontSave;
            root.SetParent(transform, false);
        }
        var cell = new GameObject($"cell {key.x},{key.y}").transform;
        cell.gameObject.hideFlags = HideFlags.DontSave;
        cell.SetParent(root, false);

        float tile = data.tile_length_m > 0 ? data.tile_length_m : 0.412f;
        float cols = data.turn_atlas_cols, rows = data.turn_atlas_rows, S = data.turn_tile_size_m;
        Vector3 origin = terrain.transform.position;
        foreach (Item it in items)
        {
            var pos = new Vector3(it.xz.x, 0f, it.xz.y);
            pos.y = origin.y + terrain.SampleHeight(pos);
            float h = it.heading * Mathf.Deg2Rad;
            var dir = new Vector3(Mathf.Sin(h), 0f, Mathf.Cos(h));   // heading is clockwise from north (+Z)

            // Not saved with the scene. Note: HideInHierarchy must NOT be used - URP skips decals on hidden objects.
            var go = new GameObject(it.turn ? "turn" : "rut") { hideFlags = HideFlags.DontSave };
            go.transform.SetParent(cell, false);
            go.transform.SetPositionAndRotation(pos, Quaternion.LookRotation(Vector3.down, dir));   // project straight down
            var d = go.AddComponent<DecalProjector>();
            d.pivot = Vector3.zero;
            d.drawDistance = drawDistance;
            d.fadeScale = 1f;   // no fade towards the box's top/bottom (it caused a "brick" pattern on slopes)
            d.startAngleFade = 60f;
            d.endAngleFade = 85f;
            d.fadeFactor = strength * it.fade;
            if (it.turn)
            {
                // Tile frame = rover frame at the start of the turn: texture up = initial heading.
                d.material = turnMaterial;
                d.size = new Vector3(S, S, projectionDepth);
                int col = it.tile % (int)cols, rowFromTop = it.tile / (int)cols;
                d.uvScale = new Vector2(1f / cols, 1f / rows);
                d.uvBias = new Vector2(col / cols, 1f - (rowFromTop + 1) / rows);   // atlas row 0 is the top of the image
            }
            else
            {
                d.material = rutMaterial;
                d.size = new Vector3(it.width, it.length, projectionDepth);   // V runs along the direction of travel
                d.uvScale = new Vector2(1f, it.length / tile);
                d.uvBias = new Vector2(0f, it.uvBias);
            }
        }
        return cell;
    }

    void ClearLive()
    {
        live.Clear();
        if (root == null) root = transform.Find(RootName);
        if (root != null) DestroyObj(root.gameObject);
        root = null;
    }

    static void DestroyObj(GameObject go)
    {
        if (go == null) return;
        if (Application.isPlaying) Destroy(go); else DestroyImmediate(go);
    }
}
